create table if not exists public.dreem_notification_endpoints(id uuid primary key default gen_random_uuid(),school_id uuid not null,user_id uuid not null,channel text not null check(channel in('email','sms','whatsapp','push')),endpoint text not null,enabled boolean not null default true,verified boolean not null default false,verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(school_id,user_id,channel,endpoint));create index if not exists dreem_notification_endpoints_user_idx on public.dreem_notification_endpoints(user_id,school_id,channel);alter table public.dreem_notification_endpoints enable row level security;revoke all on public.dreem_notification_endpoints from anon;grant select,insert,update,delete on public.dreem_notification_endpoints to authenticated;create policy "users manage own notification endpoints" on public.dreem_notification_endpoints for all to authenticated using(user_id=(select auth.uid()))with check(user_id=(select auth.uid())and private.dreem_is_member(school_id));create policy "school admins inspect notification endpoints" on public.dreem_notification_endpoints for select to authenticated using(private.dreem_has_role(school_id,array['leadership','support']));
create or replace function public.dreem_register_notification_endpoint(p_school_id uuid,p_channel text,p_endpoint text)returns uuid language plpgsql security definer set search_path='' as $$declare v_id uuid;begin if p_channel not in('email','sms','whatsapp','push')then raise exception 'Invalid notification channel';end if;if not private.dreem_is_member(p_school_id)then raise exception 'School membership required';end if;if length(trim(p_endpoint))<3 then raise exception 'Notification endpoint is required';end if;insert into public.dreem_notification_endpoints(school_id,user_id,channel,endpoint,enabled,verified)values(p_school_id,(select auth.uid()),p_channel,trim(p_endpoint),true,false)on conflict(school_id,user_id,channel,endpoint)do update set enabled=true,updated_at=now()returning id into v_id;return v_id;end;$$;revoke all on function public.dreem_register_notification_endpoint(uuid,text,text) from public;grant execute on function public.dreem_register_notification_endpoint(uuid,text,text) to authenticated;
create or replace function public.dreem_queue_announcement_delivery(p_announcement_id uuid)returns integer language plpgsql security definer set search_path='' as $$declare a public.dreem_announcements%rowtype;v_count integer:=0;v_external integer:=0;begin select * into a from public.dreem_announcements where id=p_announcement_id;if not found then raise exception 'Announcement not found';end if;if a.publication_status<>'published'then raise exception 'Only published announcements can be delivered';end if;if not private.dreem_has_role(a.school_id,array['leadership','support'])and a.created_by<>(select auth.uid())then raise exception 'You do not have permission to queue this announcement';end if;insert into public.dreem_notification_deliveries(school_id,announcement_id,recipient_user_id,channel,status)select a.school_id,a.id,m.profile_id,'in_app','queued' from public.dreem_school_memberships m where m.school_id=a.school_id and m.status='approved'and(a.audience='all'or(a.audience='staff'and m.role not in('parent','student'))or(a.audience='families'and m.role='parent')or(a.audience='students'and m.role='student'))on conflict(announcement_id,recipient_user_id,channel)do nothing;get diagnostics v_count=row_count;insert into public.dreem_notification_deliveries(school_id,announcement_id,recipient_user_id,channel,status)select a.school_id,a.id,e.user_id,e.channel,'queued' from public.dreem_notification_endpoints e join public.dreem_school_memberships m on m.profile_id=e.user_id and m.school_id=e.school_id and m.status='approved'where e.school_id=a.school_id and e.enabled and e.verified and(a.audience='all'or(a.audience='staff'and m.role not in('parent','student'))or(a.audience='families'and m.role='parent')or(a.audience='students'and m.role='student'))on conflict(announcement_id,recipient_user_id,channel)do nothing;get diagnostics v_external=row_count;insert into public.dreem_domain_events(school_id,aggregate_type,aggregate_id,event_type,idempotency_key,payload,status)values(a.school_id,'announcement',a.id,'ANNOUNCEMENT_DELIVERY_QUEUED','announcement-delivery:'||a.id::text,jsonb_build_object('announcement_id',a.id,'audience',a.audience,'priority',a.priority,'in_app_count',v_count,'external_count',v_external),'pending')on conflict do nothing;insert into public.audit_events(school_id,actor_id,action,entity_type,entity_id,detail)values(a.school_id,(select auth.uid()),'announcement.delivery_queued','announcement',a.id,jsonb_build_object('audience',a.audience,'priority',a.priority,'in_app_count',v_count,'external_count',v_external));return v_count+v_external;end;$$;revoke all on function public.dreem_queue_announcement_delivery(uuid) from public;grant execute on function public.dreem_queue_announcement_delivery(uuid) to authenticated;
create or replace view public.dreem_notification_delivery_summary as select school_id,announcement_id,channel,status,count(*)::bigint as deliveries,max(updated_at)as last_updated_at from public.dreem_notification_deliveries group by school_id,announcement_id,channel,status;revoke all on public.dreem_notification_delivery_summary from anon;grant select on public.dreem_notification_delivery_summary to authenticated;